module.zone_transfer.fix_snippet:
# BIND
zone "example.com" {
    type master;
    file "/etc/bind/db.example.com";
    allow-transfer { 203.0.113.10; };
};

# NSD
zone:
    name: "example.com"
    zonefile: "example.com.zone"
    provide-xfr: 203.0.113.10 NOKEY

# PowerDNS
allow-axfr-ips=203.0.113.10

# PowerShell
Set-DnsServerPrimaryZone -Name "example.com" -SecureSecondaries TransferToSecureServers -SecondaryServers "203.0.113.10"

# Bash
dig +short NS example.com
dig AXFR example.com @ns1.example.net
